553  int HashMgr::load_tables(const char* tpath, const char* key) {
   554    // open dictionary file
   555    FileMgr* dict = new FileMgr(tpath, key);
   556    if (dict == NULL)
   557      return 1;
   558
   559    // first read the first line of file to get hash table size
   560    std::string ts;
   561    if (!dict->getline(ts)) {
   562      HUNSPELL_WARNING(stderr, "error: empty dic file %s\n", tpath);
   563      delete dict;
   564      return 2;
   565    }
   566    mychomp(ts);
   567
   568    /* remove byte order mark */
   569    if (ts.compare(0, 3, "\xEF\xBB\xBF", 3) == 0) {
   570      ts.erase(0, 3);
   571    }
   572
   573    int tablesize = atoi(ts.c_str());
   574
   575    const int nExtra = 5 + USERWORD;
   576  #if !defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
   577    const int max_allowed = (std::numeric_limits<int>::max() - 1 - nExtra) / int(sizeof(struct hentry*));
   578  #else
   579    const int max_allowed = (268435456 - 1 - nExtra) / int(sizeof(struct hentry*));
   580  #endif
   581
   582    if (tablesize <= 0 || tablesize >= max_allowed) {
   583      HUNSPELL_WARNING(
   584          stderr, "error: line 1: missing or bad word count in the dic file\n");
   585      delete dict;
   586      return 4;
   587    }
   588    tablesize += nExtra;
   589    if ((tablesize % 2) == 0)
   590      tablesize++;
   591
   592    // allocate the hash table
   593    tableptr.resize(tablesize, nullptr);
   594
   595    // loop through all words on much list and add to hash
   596    // table and create word and affix strings
   597
   598    std::vector<w_char> workbuf;
   599
   600    while (dict->getline(ts)) {
   601      mychomp(ts);
   602      // split each line into word and morphological description
   603      size_t dp_pos = 0;
   604      while ((dp_pos = ts.find(':', dp_pos)) != std::string::npos) {
   605        if ((dp_pos > 3) && (ts[dp_pos - 3] == ' ' || ts[dp_pos - 3] == '\t')) {
   606          for (dp_pos -= 3; dp_pos > 0 && (ts[dp_pos-1] == ' ' || ts[dp_pos-1] == '\t'); --dp_pos)
   607            ;
   608          if (dp_pos == 0) {  // missing word
   609            dp_pos = std::string::npos;
   610          } else {
   611            ++dp_pos;
   612          }
   613          break;
   614        }
   615        ++dp_pos;
   616      }
   617
   618      // tabulator is the old morphological field separator
   619      size_t dp2_pos = ts.find('\t');
   620      if (dp2_pos != std::string::npos && (dp_pos == std::string::npos || dp2_pos < dp_pos)) {
   621        dp_pos = dp2_pos + 1;
   622      }
   623
   624      std::string dp;
   625      if (dp_pos != std::string::npos) {
   626        dp.assign(ts.substr(dp_pos));
   627        ts.resize(dp_pos - 1);
   628      }
   629
   630      // split each line into word and affix char strings
   631      // "\/" signs slash in words (not affix separator)
   632      // "/" at beginning of the line is word character (not affix separator)
   633      size_t ap_pos = ts.find('/');
   634      while (ap_pos != std::string::npos) {
   635        if (ap_pos == 0) {
   636          ++ap_pos;
   637          continue;
   638        } else if (ts[ap_pos - 1] != '\\')
   639          break;
   640        // replace "\/" with "/"
   641        ts.erase(ap_pos - 1, 1);
   642        ap_pos = ts.find('/', ap_pos);
   643      }
   644
   645      unsigned short* flags;
   646      int al;
   647      if (ap_pos != std::string::npos && ap_pos != ts.size()) {
   648        std::string ap(ts.substr(ap_pos + 1));
   649        ts.resize(ap_pos);
   650        if (!aliasf.empty()) {
   651          int index = atoi(ap.c_str());
   652          al = get_aliasf(index, &flags, dict);
   653          if (!al) {
   654            HUNSPELL_WARNING(stderr, "error: line %d: bad flag vector alias\n",
   655                             dict->getlinenum());
   656          }
   657        } else {
   658          al = decode_flags(&flags, ap.c_str(), dict);
   659          if (al == -1) {
   660            HUNSPELL_WARNING(stderr, "Can't allocate memory.\n");
   660            HUNSPELL_WARNING(stderr, "Can't allocate memory.\n");
   661            delete dict;
   662            return 6;
   663          }
   664          std::sort(flags, flags + al);
   665        }
   666      } else {
   667        al = 0;
   668        flags = NULL;
   669      }
   670
   671      int captype;
   672      int wcl = get_clen_and_captype(ts, &captype, workbuf);
   673      const std::string *dp_str = dp.empty() ? NULL : &dp;
   674      // add the word and its index plus its capitalized form optionally
   675      if (add_word(ts, wcl, flags, al, dp_str, false, captype) ||
   676          add_hidden_capitalized_word(ts, wcl, flags, al, dp_str, captype)) {
   677        delete dict;
   678        return 5;
   679      }
   680    }
   681
   682    delete dict;
   683    return 0;
   684  }
